using GestionTubos.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace GestionTubos.Infrastructure.Configurations;
public sealed class TuboConfiguration:IEntityTypeConfiguration<Tubo>{public void Configure(EntityTypeBuilder<Tubo>b){b.ToTable("Tubos");b.HasKey(x=>x.Id);b.Property(x=>x.CodigoInterno).HasMaxLength(50).IsRequired();b.HasIndex(x=>x.CodigoInterno).IsUnique();b.Property(x=>x.NumeroSerie).HasMaxLength(100);b.Property(x=>x.IdentificacionGrabada).HasMaxLength(100);b.Property(x=>x.Marca).HasMaxLength(100);b.Property(x=>x.Fabricante).HasMaxLength(150);b.Property(x=>x.NombrePropietarioExterno).HasMaxLength(200);b.Property(x=>x.Observaciones).HasMaxLength(1000);b.HasOne(x=>x.TipoGas).WithMany().HasForeignKey(x=>x.TipoGasId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.CapacidadTubo).WithMany().HasForeignKey(x=>x.CapacidadTuboId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Ubicacion).WithMany().HasForeignKey(x=>x.UbicacionId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.ClientePropietario).WithMany().HasForeignKey(x=>x.ClientePropietarioId).OnDelete(DeleteBehavior.Restrict);b.HasQueryFilter(x=>x.Activo);}}
